using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalBuildingFlagsFinish{
static BindingFlags F=BindingFlags.Static|BindingFlags.NonPublic;
static FinalBuildingFlagsFinish(){EditorApplication.update+=Poll;}static void Poll(){if(!EditorApplication.isCompiling&&File.Exists("FinalFlagsPortrait.request")){File.Delete("FinalFlagsPortrait.request");typeof(FinalFlagsPortrait).GetMethod("Run",F).Invoke(null,null);return;}if(!File.Exists("FinalBuildingFlagsFinish.request")||EditorApplication.isCompiling)return;File.Delete("FinalBuildingFlagsFinish.request");Run();}
static void Run(){var log=new StringBuilder();try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=s.GetRootGameObjects().Single(g=>g.name=="City Building Flags - 20 Buildings");var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/CityBuildingFlags/Building Atlas Waving Flags.mat");var flags=root.GetComponentsInChildren<MeshRenderer>();var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/CityBuildingFlags/City Building Flags.prefab");
if(root.transform.childCount!=20||flags.Length!=80||prefab.GetComponentsInChildren<MeshRenderer>().Length!=80||flags.Select(r=>r.sharedMaterial).Distinct().Count()!=1||flags.Select(r=>r.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()!=4)throw new Exception("Counts/atlas reuse failed");foreach(var b in root.transform.Cast<Transform>())if(b.GetComponentsInChildren<MeshRenderer>().Length!=4||!b.GetComponent<LODGroup>())throw new Exception("Building count invalid");
foreach(var shader in new[]{mat.shader,AssetDatabase.LoadAssetAtPath<Shader>("Assets/Scenes/Oasis/CityDetail/Shaders/City Detail Mobile.shader")})if(ShaderUtil.GetShaderMessages(shader).Any(v=>v.severity.ToString()=="Error"))throw new Exception("Shader error");
var controller=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=controller.IsNight;try{controller.ApplyDay();int i=0;foreach(var b in root.transform.Cast<Transform>().Take(3)){var mounts=b.Cast<Transform>().ToArray();var n=mounts[0].forward;var right=mounts[0].right;var target=mounts.Select(t=>t.position).Aggregate(Vector3.zero,(a,c)=>a+c)/4+Vector3.up*.8f+n*1.2f;typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{s,target+n*9+right*17-Vector3.up*2,target,"Building-Flags-Side-"+(++i)});}}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}
var b0=root.transform.GetChild(0);var t0=b0.Cast<Transform>().ToArray();var n0=t0[0].forward;var right0=t0[0].right;var target0=t0.Select(t=>t.position).Aggregate(Vector3.zero,(a,c)=>a+c)/4+Vector3.up*.8f+n0*1.2f;try{for(int frame=0;frame<2;frame++){mat.SetFloat("_PreviewTime",frame*1.25f);typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{s,target0+n0*9+right0*17-Vector3.up*2,target0,"Building-Flags-Wind-"+frame});}}finally{mat.SetFloat("_PreviewTime",-1);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();}var atlas=mat.GetTexture("_Atlas");var importer=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(atlas));log.AppendLine("SUCCESS: 20 building groups; 80 nested prefab flags; 20 per country; 4 shared meshes; one shared atlas/material; 20 LOD groups; 14080 triangles; shader errors=0; Android/iPhone ASTC6x6; moving cloth with fixed upper edge; no CPU cloth/scripts/lights/colliders; atlas="+AssetDatabase.GetAssetPath(atlas));
EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/BuildingFlagsValidation.txt",log.ToString());}}
